    <style>
        * { font-family: 'Inter', system-ui, sans-serif; }
        body { background-color: #f9fafb; }
        body.dark { background-color: #131212 !important; }
        body.dark .bg-white, body.dark .bg-card, body.dark .rounded-lg.border { background-color: #131212 !important; border-color: #333 !important; }
        body.dark .text-gray-900, body.dark .text-gray-800, body.dark .text-gray-700 { color: #e5e5e5 !important; }
        body.dark .bg-gray-100, body.dark .bg-muted { background-color: #262626 !important; }
        body.dark input, body.dark textarea, body.dark .select-trigger { background-color: #262626 !important; border-color: #404040 !important; color: #e5e5e5 !important; }
        ::-webkit-scrollbar { width: 6px; height: 6px; }
        ::-webkit-scrollbar-track { background: #f1f1f1; border-radius: 10px; }
        ::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        
        /* Tab styling - matching ambulance-details.html exactly */
        .tab-trigger { transition: all 0.2s ease; }
        .tab-trigger.active { background-color: white; color: #1f2937; box-shadow: 0 1px 2px 0 rgba(0,0,0,0.05); }
        body.dark .tab-trigger.active { background-color: #131212; color: #e5e5e5; }
        .tab-panel { animation: fadeIn 0.2s ease-out; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }    
        
        /* Action Menu Styles - matching test requests example */
.action-menu {
    position: fixed;
    z-index: 100;
    min-width: 180px;
    background: white;
    border-radius: 0.5rem;
    border: 1px solid #e5e7eb;
    box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1);
    padding: 0.25rem;
    animation: fadeIn 0.12s ease-out;
}
body.dark .action-menu {
    background: #2a2a2a;
    border-color: #404040;
}
.action-menu-header {
    padding: 0.5rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #6b7280;
    border-bottom: 1px solid #e5e7eb;
    margin-bottom: 0.25rem;
}
body.dark .action-menu-header {
    border-bottom-color: #404040;
    color: #9ca3af;
}
.action-item {
    padding: 0.5rem 0.75rem;
    font-size: 0.875rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    border-radius: 0.25rem;
    transition: background 0.1s;
    width: 100%;
    background: transparent;
    border: none;
}
.action-item:hover {
    background-color: #f3f4f6;
}
body.dark .action-item:hover {
    background-color: #3f3f46;
}
.action-divider {
    height: 1px;
    background-color: #e5e7eb;
    margin: 0.25rem 0;
}
body.dark .action-divider {
    background-color: #404040;
}

/* Toast Message Styles */
.toast-message {
    position: fixed;
    bottom: 20px;
    right: 20px;
    background: #10b981;
    color: white;
    padding: 12px 20px;
    border-radius: 8px;
    z-index: 1000;
    animation: slideIn 0.3s ease-out;
    font-size: 0.875rem;
}
.toast-message.error {
    background: #ef4444;
}
@keyframes slideIn {
    from { transform: translateX(100%); opacity: 0; }
    to { transform: translateX(0); opacity: 0; }
}

/* Modal Styles */
.modal-overlay {
    position: fixed;
    inset: 0;
    background-color: rgb(0 0 0 / 87%);
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: center;
    animation: fadeIn 0.2s ease-out;
}
@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

.modal-container {
    background: white;
    border-radius: 0.75rem;
    width: 100%;
    max-width: 600px;
    max-height: 85vh;
    overflow-y: auto;
    box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25);
    animation: slideUp 0.2s ease;
    position: relative;
}
body.dark .modal-container {
    background: #131212;
    border-color: #333;
}
.modal-container.large {
    max-width: 800px;
}
@keyframes slideUp {
    from { transform: translateY(20px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}

.modal-header {
    padding: 1rem 1.5rem;
    border-bottom: 1px solid #e5e7eb;
    display: flex;
    justify-content: space-between;
    align-items: center;
    position: sticky;
    top: 0;
    background: white;
    z-index: 10;
}
body.dark .modal-header {
    border-bottom-color: #404040;
    background: #131212;
}
.modal-title {
    font-size: 1.125rem;
    font-weight: 600;
}
.modal-close {
    background: transparent;
    border: none;
    font-size: 1.5rem;
    cursor: pointer;
    color: #6b7280;
    transition: color 0.1s;
    line-height: 1;
    padding: 0;
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 0.375rem;
}
.modal-close:hover {
    color: #1f2937;
    background-color: #f3f4f6;
}
body.dark .modal-close {
    color: #9ca3af;
}
body.dark .modal-close:hover {
    color: #e5e5e5;
    background-color: #374151;
}

.modal-body {
    padding: 1.5rem;
}
.modal-footer {
    padding: 1rem 1.5rem;
    border-top: 1px solid #e5e7eb;
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    position: sticky;
    bottom: 0;
    background: white;
}
body.dark .modal-footer {
    border-top-color: #404040;
    background: #131212;
}


/* Alert Dialog Styles - Matching the requested design */
.alert-dialog-overlay {
    position: fixed;
    inset: 0;
    background-color: rgb(0 0 0 / 87%);
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: center;
    animation: fadeIn 0.2s ease-out;
}

.alert-dialog {
    background-color: white;
    border-radius: 0.75rem;
    width: 90%;
    max-width: 450px;
    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
    animation: slideUp 0.2s ease;
    overflow: hidden;
}

body.dark .alert-dialog {
    background-color: #1f1f1f;
    border: 1px solid #333;
}

.alert-dialog-header {
    padding: 1.5rem 1.5rem 0.75rem 1.5rem;
}

.alert-dialog-title {
    font-size: 1.125rem;
    font-weight: 600;
    line-height: 1.5;
    color: #111827;
    margin: 0 0 0.5rem 0;
}

body.dark .alert-dialog-title {
    color: #f3f4f6;
}

.alert-dialog-description {
    font-size: 0.875rem;
    color: #6b7280;
    line-height: 1.5;
    margin: 0;
}

body.dark .alert-dialog-description {
    color: #9ca3af;
}

.alert-dialog-footer {
    padding: 1rem 1.5rem 1.5rem 1.5rem;
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
}

.alert-dialog-cancel {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 0.5rem;
    padding: 0.5rem 1rem;
    font-size: 0.875rem;
    font-weight: 500;
    background-color: transparent;
    border: 1px solid #e5e7eb;
    color: #374151;
    cursor: pointer;
    transition: all 0.1s ease;
}

.alert-dialog-cancel:hover {
    background-color: #f9fafb;
    border-color: #d1d5db;
}

body.dark .alert-dialog-cancel {
    border-color: #404040;
    color: #e5e5e5;
}

body.dark .alert-dialog-cancel:hover {
    background-color: #2a2a2a;
}

.alert-dialog-delete {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 0.5rem;
    padding: 0.5rem 1rem;
    font-size: 0.875rem;
    font-weight: 500;
    background-color: #ef4444;
    border: none;
    color: white;
    cursor: pointer;
    transition: all 0.1s ease;
}

.alert-dialog-delete:hover {
    background-color: #dc2626;
}

body.dark .alert-dialog-delete {
    background-color: #dc2626;
}

body.dark .alert-dialog-delete:hover {
    background-color: #b91c1c;
}

/* Animation keyframes if not already defined */
@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes slideUp {
    from { transform: translateY(10px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}

/* Dropdown animation */
.dropdown-animation {
    animation: fadeInScale 0.12s ease-out;
}
@keyframes fadeInScale {
    from { opacity: 0; transform: scale(0.95); }
    to { opacity: 1; transform: scale(1); }
}

/* Filter option hover states */
.filter-option:hover {
    background-color: #f3f4f6;
}
body.dark .filter-option:hover {
    background-color: #3f3f46;
}
.filter-option[data-value="all"] {
    font-weight: 500;
    color: #6b7280;
}
        </style>
