];

let currentTab = "all";
let searchQuery = "";
let statusFilter = "all";
let typeFilter = "all";
let activeMenu = null;
let activeModal = null;

// --- Helper Functions ---
function showToast(message, isError = false) {
    const existing = document.querySelector('.toast-message');
    if (existing) existing.remove();
    const toast = document.createElement('div');
    toast.className = `toast-message ${isError ? 'error' : ''}`;
    toast.textContent = message;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 3000);
}

function closeMenu() {
    if (activeMenu) {
        activeMenu.remove();
        activeMenu = null;
    }
}

function closeModal() {
    if (activeModal) {
        activeModal.remove();
        activeModal = null;
    }
}

function getStatusBadge(status) {
    const colors = { 
        Available: "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200", 
        "On Call": "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200", 
        Maintenance: "bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200" 
    };
    return `<span class="inline-flex rounded-full px-2.5 py-0.5 text-xs font-semibold ${colors[status] || 'bg-gray-100'}">${status}</span>`;
}

// --- Action Menu (matching test requests behavior) ---
function showActionMenu(btn, ambulance) {
    closeMenu();
    const rect = btn.getBoundingClientRect();
    const menu = document.createElement('div');
    menu.className = 'action-menu';
    
    // Position with boundary detection
    let left = rect.left;
    let top = rect.bottom + 6;
    if (left + 200 > window.innerWidth) left = window.innerWidth - 210;
    if (top + 300 > window.innerHeight) top = rect.top - 320;
    
    menu.style.top = `${top}px`;
    menu.style.left = `${left}px`;
    
    menu.innerHTML = `
        <div class="action-menu-header">Ambulance Actions</div>
        <button data-action="view" class="action-item">
            <svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"></path><circle cx="12" cy="12" r="3"></circle></svg>
            View Details
        </button>
        <button data-action="edit" class="action-item">
            <svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"></path><path d="m15 5 4 4"></path></svg>
            Edit Ambulance
        </button>
        <button data-action="updateStatus" class="action-item">
            <svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"></path><path d="M3 3v5h5"></path></svg>
            Update Status
        </button>
        <button data-action="assignDriver" class="action-item">
            <svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><line x1="19" x2="19" y1="8" y2="14"></line><line x1="22" x2="16" y1="11" y2="11"></line></svg>
            Assign Driver
        </button>
        <button data-action="maintenance" class="action-item">
            <svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"></path></svg>
            Maintenance Log
        </button>
        <div class="action-divider"></div>
        <button data-action="delete" class="action-item text-red-600">
            <svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18"></path><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"></path><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"></path></svg>
            Delete Ambulance
        </button>
    `;
    
    document.body.appendChild(menu);
    activeMenu = menu;
    
    // Close handler
    const closeHandler = (e) => {
        if (!menu.contains(e.target) && e.target !== btn) {
            closeMenu();
            document.removeEventListener('click', closeHandler);
        }
    };
    setTimeout(() => document.addEventListener('click', closeHandler), 10);
    
    // Action handlers
    menu.querySelector('[data-action="view"]')?.addEventListener('click', () => { showViewModal(ambulance); closeMenu(); });
    menu.querySelector('[data-action="edit"]')?.addEventListener('click', () => { showEditModal(ambulance); closeMenu(); });
    menu.querySelector('[data-action="updateStatus"]')?.addEventListener('click', () => { showUpdateStatusModal(ambulance); closeMenu(); });
    menu.querySelector('[data-action="assignDriver"]')?.addEventListener('click', () => { showAssignDriverModal(ambulance); closeMenu(); });
    menu.querySelector('[data-action="maintenance"]')?.addEventListener('click', () => { showMaintenanceModal(ambulance); closeMenu(); });
    menu.querySelector('[data-action="delete"]')?.addEventListener('click', () => { showDeleteConfirm(ambulance); closeMenu(); });
}

// --- Modals ---
function showViewModal(ambulance) {
    // Navigate to ambulance-details.html with the ambulance ID as a query parameter
    window.location.href = `ambulance-details.html?id=${ambulance.id}`;
}

function showEditModal(ambulance) {
    // Navigate to edit-ambulance-details.html with the ambulance ID as a query parameter
    window.location.href = `edit-ambulance-details.html?id=${ambulance.id}`;
}

function showUpdateStatusModal(ambulance) {
    closeModal();
    const modal = document.createElement('div');
    modal.className = 'modal-overlay';
    modal.innerHTML = `
        <div class="modal-container">
            <div class="modal-header">
                <h2 class="modal-title">Update Status - ${ambulance.regNo}</h2>
                <button class="modal-close">&times;</button>
            </div>
            <div class="modal-body">
                <div class="space-y-4">
                    <div>
                        <label class="text-sm font-medium block mb-2">Current Status: ${getStatusBadge(ambulance.status)}</label>
                        <select id="newStatus" class="w-full rounded-md border border-gray-300 px-3 py-2 text-sm">
                            <option value="Available" ${ambulance.status === 'Available' ? 'selected' : ''}>Available</option>
                            <option value="On Call" ${ambulance.status === 'On Call' ? 'selected' : ''}>On Call</option>
                            <option value="Maintenance" ${ambulance.status === 'Maintenance' ? 'selected' : ''}>Maintenance</option>
                        </select>
                    </div>
                    <div>
                        <label class="text-sm font-medium block mb-1">Notes (optional)</label>
                        <textarea id="statusNotes" rows="3" class="w-full rounded-md border border-gray-300 px-3 py-2 text-sm" placeholder="Reason for status change..."></textarea>
                    </div>
                </div>
            </div>
            <div class="modal-footer">
                <button class="cancel-modal inline-flex rounded-md border px-4 py-2 text-sm hover:bg-gray-100">Cancel</button>
                <button id="updateStatusBtn" class="inline-flex rounded-md bg-primary px-4 py-2 text-sm text-white hover:bg-primary/90">Update Status</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    activeModal = modal;
    
    modal.querySelector('.modal-close')?.addEventListener('click', () => closeModal());
    modal.querySelector('.cancel-modal')?.addEventListener('click', () => closeModal());
    modal.querySelector('#updateStatusBtn')?.addEventListener('click', () => {
        const newStatus = modal.querySelector('#newStatus').value;
        ambulance.status = newStatus;
        renderTable();
        showToast(`Status updated to ${newStatus}`);
        closeModal();
    });
}

function showAssignDriverModal(ambulance) {
    closeModal();
    const modal = document.createElement('div');
    modal.className = 'modal-overlay';
    modal.innerHTML = `
        <div class="modal-container">
            <div class="modal-header">
                <h2 class="modal-title">Assign Driver - ${ambulance.regNo}</h2>
                <button class="modal-close">&times;</button>
            </div>
            <div class="modal-body">
                <div class="space-y-4">
                    <div>
                        <label class="text-sm font-medium block mb-1">Current Driver</label>
                        <p class="text-sm text-gray-600">${ambulance.driver || 'Not assigned'}</p>
                    </div>
                    <div>
                        <label class="text-sm font-medium block mb-1">New Driver Name</label>
                        <input type="text" id="driverName" value="${ambulance.driver || ''}" class="w-full rounded-md border border-gray-300 px-3 py-2 text-sm" placeholder="Enter driver name">
                    </div>
                    <div>
                        <label class="text-sm font-medium block mb-1">Driver Contact (optional)</label>
                        <input type="text" id="driverContact" class="w-full rounded-md border border-gray-300 px-3 py-2 text-sm" placeholder="Phone number">
                    </div>
                </div>
            </div>
            <div class="modal-footer">
                <button class="cancel-modal inline-flex rounded-md border px-4 py-2 text-sm hover:bg-gray-100">Cancel</button>
                <button id="assignDriverBtn" class="inline-flex rounded-md bg-primary px-4 py-2 text-sm text-white hover:bg-primary/90">Assign Driver</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    activeModal = modal;
    
    modal.querySelector('.modal-close')?.addEventListener('click', () => closeModal());
    modal.querySelector('.cancel-modal')?.addEventListener('click', () => closeModal());
    modal.querySelector('#assignDriverBtn')?.addEventListener('click', () => {
        const newDriver = modal.querySelector('#driverName').value;
        if (newDriver && newDriver.trim()) {
            ambulance.driver = newDriver.trim();
            renderTable();
            showToast(`Driver assigned to ${ambulance.regNo}: ${newDriver}`);
            closeModal();
        } else {
            showToast('Please enter a driver name', true);
        }
    });
}

function showMaintenanceModal(ambulance) {
    closeModal();
    const modal = document.createElement('div');
    modal.className = 'modal-overlay';
    modal.innerHTML = `
        <div class="modal-container">
            <div class="modal-header">
                <h2 class="modal-title">Maintenance Log - ${ambulance.regNo}</h2>
                <button class="modal-close">&times;</button>
            </div>
            <div class="modal-body">
                <div class="space-y-4">
                    <div class="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-md">
                        <p class="text-sm"><strong>Last Maintenance:</strong> ${ambulance.lastMaintenance || 'Not recorded'}</p>
                        <p class="text-sm mt-1"><strong>Next Maintenance Due:</strong> ${ambulance.nextMaintenance || 'Not scheduled'}</p>
                        <p class="text-sm mt-1"><strong>Current Mileage:</strong> ${ambulance.mileage || 'N/A'}</p>
                    </div>
                    <div>
                        <label class="text-sm font-medium block mb-1">Maintenance Type</label>
                        <select id="maintenanceType" class="w-full rounded-md border border-gray-300 px-3 py-2 text-sm">
                            <option value="Regular Service">Regular Service</option>
                            <option value="Emergency Repair">Emergency Repair</option>
                            <option value="Parts Replacement">Parts Replacement</option>
                            <option value="Inspection">Inspection</option>
                        </select>
                    </div>
                    <div>
                        <label class="text-sm font-medium block mb-1">Work Performed</label>
                        <textarea id="workPerformed" rows="3" class="w-full rounded-md border border-gray-300 px-3 py-2 text-sm" placeholder="Describe maintenance work..."></textarea>
                    </div>
                    <div>
                        <label class="text-sm font-medium block mb-1">Cost ($)</label>
                        <input type="number" id="cost" class="w-full rounded-md border border-gray-300 px-3 py-2 text-sm" placeholder="0.00">
                    </div>
                </div>
            </div>
            <div class="modal-footer">
                <button class="cancel-modal inline-flex rounded-md border px-4 py-2 text-sm hover:bg-gray-100">Cancel</button>
                <button id="logMaintenanceBtn" class="inline-flex rounded-md bg-primary px-4 py-2 text-sm text-white hover:bg-primary/90">Record Maintenance</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    activeModal = modal;
    
    modal.querySelector('.modal-close')?.addEventListener('click', () => closeModal());
    modal.querySelector('.cancel-modal')?.addEventListener('click', () => closeModal());
    modal.querySelector('#logMaintenanceBtn')?.addEventListener('click', () => {
        const today = new Date().toISOString().split('T')[0];
        ambulance.lastMaintenance = today;
        // Set next maintenance to 3 months from now
        const nextDate = new Date();
        nextDate.setMonth(nextDate.getMonth() + 3);
        ambulance.nextMaintenance = nextDate.toISOString().split('T')[0];
        ambulance.status = 'Maintenance';
        renderTable();
        showToast(`Maintenance recorded for ${ambulance.regNo}`);
        closeModal();
    });
}

function showDeleteConfirm(ambulance) {
    // Close any existing modal first
    if (activeModal) {
        activeModal.remove();
        activeModal = null;
    }
    
    const modal = document.createElement('div');
    modal.id = "deleteConfirmModal";
    modal.className = "alert-dialog-overlay";
    modal.innerHTML = `
        <div role="alertdialog" class="alert-dialog">
            <div class="alert-dialog-header">
                <h2 id="deleteModalTitle" class="alert-dialog-title">Are you sure you want to Delete this ambulance?</h2>
                <p id="deleteModalDesc" class="alert-dialog-description">This action cannot be undone. The ambulance "${ambulance.regNo}" will be permanently removed from the fleet.</p>
            </div>
            <div class="alert-dialog-footer">
                <button type="button" id="deleteModalCancel" class="alert-dialog-cancel">Cancel</button>
                <button type="button" id="deleteModalConfirm" class="alert-dialog-delete">Delete</button>
            </div>
        </div>
    `;
    
    document.body.appendChild(modal);
    activeModal = modal;
    
    // Add event listeners
    modal.querySelector('#deleteModalCancel')?.addEventListener('click', () => {
        closeModal();
    });
    
    modal.querySelector('#deleteModalConfirm')?.addEventListener('click', () => {
        const index = ambulances.findIndex(a => a.id === ambulance.id);
        if (index !== -1) {
            ambulances.splice(index, 1);
            renderTable();
            updateStats();
            showToast(`Ambulance ${ambulance.regNo} deleted successfully`);
        }
        closeModal();
    });
    
    // Close on overlay click
    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            closeModal();
        }
    });
}

// --- Filter and Render Functions ---
function getFilteredAmbulances() {
    let filtered = [...ambulances];
    if (currentTab === "available") filtered = filtered.filter(a => a.status === "Available");
    else if (currentTab === "oncall") filtered = filtered.filter(a => a.status === "On Call");
    else if (currentTab === "maintenance") filtered = filtered.filter(a => a.status === "Maintenance");
    
    if (searchQuery) {
        const q = searchQuery.toLowerCase();
        filtered = filtered.filter(a => a.regNo.toLowerCase().includes(q) || 
            a.driver.toLowerCase().includes(q) || 
            a.model.toLowerCase().includes(q));
    }
    if (statusFilter !== "all") filtered = filtered.filter(a => a.status === statusFilter);
    if (typeFilter !== "all") filtered = filtered.filter(a => a.type === typeFilter);
    return filtered;
}

function updateStats() {
    const totalCountEl = document.querySelector('.grid .text-2xl.font-bold');
    if (totalCountEl) {
        const cards = document.querySelectorAll('.grid .text-2xl.font-bold');
        if (cards[0]) cards[0].innerText = ambulances.length;
        if (cards[1]) cards[1].innerText = ambulances.filter(a => a.status === "Available").length;
        if (cards[2]) cards[2].innerText = ambulances.filter(a => a.status === "Maintenance").length;
    }
}

function renderTable() {
    const filtered = getFilteredAmbulances();
    const tbody = document.getElementById('ambulanceTableBody');
    if (!tbody) return;
    
    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" class="text-center py-10 text-gray-500">No ambulances found</td></tr>';
        return;
    }
    
    tbody.innerHTML = filtered.map(a => `
        <tr class="border-b hover:bg-gray-50 dark:hover:bg-gray-800/50">
            <td class="p-4 font-medium">AMB-${a.id.toString().padStart(3,'0')}</td>
            <td class="p-4">${a.regNo}</td>
            <td class="p-4 hidden md:table-cell">${a.model}<br><span class="text-xs text-gray-400">${a.year}</span></td>
            <td class="p-4">${a.type}</td>
            <td class="p-4">${getStatusBadge(a.status)}</td>
            <td class="p-4 hidden lg:table-cell">${a.driver || '—'}</td>
            <td class="p-4 hidden lg:table-cell">${a.location || '—'}</td>
            <td class="p-4 text-right">
                <button data-id="${a.id}" class="action-trigger inline-flex items-center justify-center h-10 w-10 rounded-md hover:bg-gray-100">
                    <svg class="h-4 w-4 text-gray-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/><circle cx="5" cy="12" r="1"/>
                    </svg>
                </button>
            </td>
        </tr>
    `).join('');
    
    // Attach action listeners
    document.querySelectorAll('.action-trigger').forEach(btn => {
        const id = parseInt(btn.dataset.id);
        const ambulance = ambulances.find(a => a.id === id);
        if (ambulance) {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                showActionMenu(btn, ambulance);
            });
        }
    });
}

// --- Event Listeners ---
document.getElementById('searchInput')?.addEventListener('input', (e) => { 
    searchQuery = e.target.value; 
    renderTable(); 
});
// --- Filter Dropdowns (Radix UI style) ---
function initFilterDropdown(btnId, dropdownId, textId, onSelect) {
    const btn = document.getElementById(btnId);
    const dropdown = document.getElementById(dropdownId);
    const textEl = document.getElementById(textId);
    
    if (!btn || !dropdown) return;
    
    btn.addEventListener('click', (e) => {
        e.stopPropagation();
        // Close other dropdowns
        document.querySelectorAll('[id$="FilterDropdown"]').forEach(d => {
            if (d !== dropdown) d.classList.add('hidden');
        });
        dropdown.classList.toggle('hidden');
    });
    
    dropdown.querySelectorAll('.filter-option').forEach(option => {
        option.addEventListener('click', () => {
            const value = option.dataset.value;
            const text = option.textContent.trim();
            textEl.textContent = text;
            dropdown.classList.add('hidden');
            if (onSelect) onSelect(value);
        });
    });
}

// Initialize filter dropdowns
initFilterDropdown('statusFilterBtn', 'statusFilterDropdown', 'statusFilterText', (value) => {
    statusFilter = value;
    renderTable();
});

initFilterDropdown('typeFilterBtn', 'typeFilterDropdown', 'typeFilterText', (value) => {
    typeFilter = value;
    renderTable();
});

// Close dropdowns when clicking outside
document.addEventListener('click', (e) => {
    if (!e.target.closest('[id$="FilterBtn"]') && !e.target.closest('[id$="FilterDropdown"]')) {
        document.querySelectorAll('[id$="FilterDropdown"]').forEach(d => d.classList.add('hidden'));
    }
});

// Tabs
const tabs = document.querySelectorAll('.tab-btn');
tabs.forEach(btn => {
    btn.addEventListener('click', () => {
        currentTab = btn.dataset.tab;
        tabs.forEach(b => b.classList.remove('bg-white', 'shadow-sm', 'text-gray-900', 'dark:bg-gray-700'));
        btn.classList.add('bg-white', 'shadow-sm', 'text-gray-900', 'dark:bg-gray-700');
        renderTable();
    });
});
// Activate first tab
document.querySelector('[data-tab="all"]')?.classList.add('bg-white', 'shadow-sm', 'text-gray-900', 'dark:bg-gray-700');

// Add Ambulance Button
document.getElementById('addAmbulanceBtn')?.addEventListener('click', () => {
    window.location.href = 'add-ambulance.html';
});

// Initial render
renderTable();
updateStats();


    </script>

    
    


